from dataclasses import dataclass, field
import json
import logging
from pathlib import Path
from typing import Any, Mapping

logger = logging.getLogger(__name__)


@dataclass(frozen=True)
class DatabaseSettings:
    host: str
    port: int
    name: str
    pool_size: int
    connect_timeout: float


@dataclass(frozen=True)
class CacheSettings:
    enabled: bool
    ttl_seconds: int
    namespace: str
    max_entries: int


@dataclass(frozen=True)
class MailSettings:
    sender: str
    retry_count: int
    batch_size: int
    dry_run: bool


@dataclass(frozen=True)
class StorageSettings:
    root: Path
    max_upload_bytes: int
    accepted_types: frozenset[str]


@dataclass(frozen=True)
class Settings:
    database: DatabaseSettings
    cache: CacheSettings
    mail: MailSettings
    storage: StorageSettings
    feature_flags: Mapping[str, bool] = field(default_factory=dict)


def object_value(value: object, field_name: str) -> dict[str, object]:
    if not isinstance(value, dict) or not all(isinstance(key, str) for key in value):
        raise ValueError(f"{field_name} must be an object")
    return value


def string_value(value: object, field_name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field_name} must be a non-empty string")
    return value.strip()


def integer_value(value: object, field_name: str, minimum: int, maximum: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{field_name} must be an integer")
    if not minimum <= value <= maximum:
        raise ValueError(f"{field_name} is out of range")
    return value


def float_value(value: object, field_name: str, minimum: float, maximum: float) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{field_name} must be a number")
    result = float(value)
    if not minimum <= result <= maximum:
        raise ValueError(f"{field_name} is out of range")
    return result


def boolean_value(value: object, field_name: str) -> bool:
    if not isinstance(value, bool):
        raise ValueError(f"{field_name} must be a boolean")
    return value


def parse_database(raw: object) -> DatabaseSettings:
    data = object_value(raw, "database")
    return DatabaseSettings(
        host=string_value(data.get("host"), "database.host"),
        port=integer_value(data.get("port", 5432), "database.port", 1, 65535),
        name=string_value(data.get("name"), "database.name"),
        pool_size=integer_value(data.get("pool_size", 10), "database.pool_size", 1, 100),
        connect_timeout=float_value(
            data.get("connect_timeout", 5.0), "database.connect_timeout", 0.1, 60.0
        ),
    )


def parse_cache(raw: object) -> CacheSettings:
    data = object_value(raw, "cache")
    return CacheSettings(
        enabled=boolean_value(data.get("enabled", True), "cache.enabled"),
        ttl_seconds=integer_value(data.get("ttl_seconds", 300), "cache.ttl_seconds", 1, 86400),
        namespace=string_value(data.get("namespace", "app"), "cache.namespace"),
        max_entries=integer_value(data.get("max_entries", 10000), "cache.max_entries", 1, 1000000),
    )


def parse_mail(raw: object) -> MailSettings:
    data = object_value(raw, "mail")
    return MailSettings(
        sender=string_value(data.get("sender"), "mail.sender"),
        retry_count=integer_value(data.get("retry_count", 3), "mail.retry_count", 0, 20),
        batch_size=integer_value(data.get("batch_size", 100), "mail.batch_size", 1, 1000),
        dry_run=boolean_value(data.get("dry_run", False), "mail.dry_run"),
    )


def resolve_storage_root(config_path: Path, value: object) -> Path:
    raw = Path(string_value(value, "storage.root"))
    base = config_path.parent.resolve()
    resolved = (base / raw).resolve()
    if base not in resolved.parents and resolved != base:
        raise ValueError("storage.root must stay beneath the config directory")
    return resolved


def parse_storage(raw: object, config_path: Path) -> StorageSettings:
    data = object_value(raw, "storage")
    types = data.get("accepted_types", ["image/png", "image/jpeg"])
    if not isinstance(types, list) or not all(isinstance(item, str) for item in types):
        raise ValueError("storage.accepted_types must be a list of strings")
    return StorageSettings(
        root=resolve_storage_root(config_path, data.get("root", "uploads")),
        max_upload_bytes=integer_value(
            data.get("max_upload_bytes", 10000000), "storage.max_upload_bytes", 1, 100000000
        ),
        accepted_types=frozenset(types),
    )


def parse_feature_flags(raw: object) -> dict[str, bool]:
    data = object_value(raw, "feature_flags")
    parsed: dict[str, bool] = {}
    for name, value in data.items():
        parsed[name] = boolean_value(value, f"feature_flags.{name}")
    return parsed


def check_unknown_keys(data: Mapping[str, object]) -> None:
    allowed = {"database", "cache", "mail", "storage", "feature_flags"}
    unknown = set(data) - allowed
    if unknown:
        raise ValueError(f"unknown settings sections: {', '.join(sorted(unknown))}")


def parse_settings(raw: object, path: Path) -> Settings:
    data = object_value(raw, "settings")
    check_unknown_keys(data)
    return Settings(
        database=parse_database(data.get("database")),
        cache=parse_cache(data.get("cache", {})),
        mail=parse_mail(data.get("mail")),
        storage=parse_storage(data.get("storage", {}), path),
        feature_flags=parse_feature_flags(data.get("feature_flags", {})),
    )


def load_settings(path: Path) -> Settings:
    try:
        raw: Any = json.loads(path.read_text(encoding="utf-8"))
        return parse_settings(raw, path)
    except Exception:
        logger.exception("failed to load application settings from %s", path)
        raise


def cache_is_enabled(settings: Settings) -> bool:
    return settings.cache.enabled and settings.cache.max_entries > 0


def allowed_upload_type(settings: Settings, content_type: str) -> bool:
    return content_type in settings.storage.accepted_types


def mail_batch_count(settings: Settings, message_count: int) -> int:
    if message_count < 0:
        raise ValueError("message count cannot be negative")
    size = settings.mail.batch_size
    return (message_count + size - 1) // size


def database_dsn_parts(settings: Settings) -> tuple[str, int, str]:
    database = settings.database
    return database.host, database.port, database.name


def as_public_dict(settings: Settings) -> dict[str, object]:
    return {
        "database": {
            "host": settings.database.host,
            "port": settings.database.port,
            "name": settings.database.name,
            "pool_size": settings.database.pool_size,
        },
        "cache": {
            "enabled": settings.cache.enabled,
            "ttl_seconds": settings.cache.ttl_seconds,
            "namespace": settings.cache.namespace,
        },
        "mail": {
            "sender": settings.mail.sender,
            "batch_size": settings.mail.batch_size,
            "dry_run": settings.mail.dry_run,
        },
        "storage": {
            "root": str(settings.storage.root),
            "max_upload_bytes": settings.storage.max_upload_bytes,
            "accepted_types": sorted(settings.storage.accepted_types),
        },
        "feature_flags": dict(settings.feature_flags),
    }
